SourceCode.Declaration:
public class METProcMetricsScope implements System.IDisposable
{
    private static METProcMetrics procMetrics;
    private boolean disposed;
    private boolean errorHandling;
    private METProcMetrics previous;

}

Method.Source:
private void new(METProcMetrics _procMetrics, boolean _errorHandling = false)
{
    previous      = procMetrics;
    procMetrics   = _procMetrics;
    errorHandling = _errorHandling;
}

public static METProcMetricsScope construct(METProcMetrics _procMetrics)
{
    return new METProcMetricsScope(_procMetrics);
}

public static METProcMetricsScope constructWithErrorHandling(METProcMetrics _procMetrics)
{
    return new METProcMetricsScope(_procMetrics, true);
}

/// <summary>
/// Access the ambient procMetrics from anywhere in the call stack.
/// Returns null if called outside a using block.
/// </summary>
public static METProcMetrics current()
{
    return procMetrics;
}

public void Dispose()
{
    if (!disposed)
    {
        if (errorHandling && procMetrics && !procMetrics.isTraceEnded())
        {
            try
            {
                procMetrics.endTrace(METBatchMonitoringStatus::Failed);
            }
            catch
            {
                // swallow any exception to avoid masking the original error
            }
        }

        procMetrics = previous;   
        previous = null;
        disposed = true;
    }
}
